def inject_back_navigation():
    """Browser Back button -> goes to Home instead of leaving the app."""
    components.html(
        """
        <script>
        (function () {
            var w = window.parent;
            if (w.__messBackInit) { return; }
            w.__messBackInit = true;

            var s = w.document.createElement("script");
            s.textContent = `
                history.pushState({mess: 1}, "", location.href);
                window.addEventListener("popstate", function () {
                    history.pushState({mess: 1}, "", location.href);
                    var btns = document.querySelectorAll(
                        'section[data-testid="stSidebar"] button'
                    );
                    for (var i = 0; i < btns.length; i++) {
                        if (btns[i].innerText.indexOf("Home") > -1) {
                            btns[i].click();
                            break;
                        }
                    }
                });
            `;
            w.document.head.appendChild(s);
        })();
        </script>
        """,
        height=0
    )


def menu_card_html(title, menu, variant):
    rows = ""
    for meal, items in menu.items():
        rows += (
            f'<div class="meal-row">'
            f'<div class="meal-name">{MEAL_ICONS[meal]} {meal}</div>'
            f'<div class="meal-items">{escape(items)}</div>'
            f'</div>'
        )
    return (
        f'<div class="menu-card {variant}">'
        f'<div class="mc-title">{escape(title)}</div>{rows}</div>'
    )


def show_menu(title, menu, variant):
    st.markdown(menu_card_html(title, menu, variant), unsafe_allow_html=True)


