def _absence_sync_all():
    """'Select All' ticked/unticked -> set all three meals."""
    value = st.session_state.get("abs_all", False)

    for key in ("abs_b", "abs_l", "abs_d"):
        st.session_state[key] = value


def _absence_sync_one():
    """Single meal changed -> keep 'Select All' in sync."""
    st.session_state["abs_all"] = all(
        st.session_state.get(k, False) for k in ("abs_b", "abs_l", "abs_d")
    )


def student_absence():

    student = st.session_state.user

    tomorrow = date.today() + timedelta(days=1)

    page_header(
        "Mark Absence",
        "Absence can start from tomorrow: " + tomorrow.strftime("%d-%m-%Y")
    )

    st.info(
        "Choose the start date, the number of days and the meals you will "
        "NOT take. You can select a single meal, any combination, or all meals. "
        "If an absence already exists for a date, it will be updated."
    )

    for key in ("abs_b", "abs_l", "abs_d", "abs_all"):
        st.session_state.setdefault(key, False)

    with st.container(border=True):

        c1, c2 = st.columns(2, gap="medium")

        with c1:

            start_date = st.date_input(
                "Start date",
                value=tomorrow,
                min_value=tomorrow,
                key="abs_start"
            )

        with c2:

            days = st.number_input(
                "Total duration (number of days)",
                min_value=1,
                max_value=30,
                value=1,
                step=1,
                key="absence_days"
            )

        st.markdown(
            '<div class="meal-hint">Select the meals you will NOT take</div>',
            unsafe_allow_html=True
        )

        st.checkbox(
            "Select All",
            key="abs_all",
            on_change=_absence_sync_all
        )

        breakfast = st.checkbox(
            "Breakfast",
            key="abs_b",
            on_change=_absence_sync_one
        )

        lunch = st.checkbox(
            "Lunch",
            key="abs_l",
            on_change=_absence_sync_one
        )

        dinner = st.checkbox(
            "Dinner",
            key="abs_d",
            on_change=_absence_sync_one
        )

        days = int(days)

        last_day = start_date + timedelta(days=days - 1)

        chosen = [
            name for name, flag in (
                ("Breakfast", breakfast),
                ("Lunch", lunch),
                ("Dinner", dinner)
            ) if flag
        ]

        # ---- live summary ----
        if chosen:

            period_text = (
                start_date.strftime("%d-%m-%Y")
                if days == 1
                else f"{start_date.strftime('%d-%m-%Y')} to {last_day.strftime('%d-%m-%Y')}"
            )

            st.markdown(
                '<div class="summary-box">'
                f'<b>Summary:</b> {escape(period_text)} &nbsp;|&nbsp; '
                f'{days} day(s) &nbsp;|&nbsp; '
                f'Meals: <b>{escape(", ".join(chosen))}</b> &nbsp;|&nbsp; '
                f'Total meals skipped: <b>{days * len(chosen)}</b>'
                '</div>',
                unsafe_allow_html=True
            )

            overlap = execute_query(
                """
                SELECT COUNT(*) AS c
                FROM student_absence
                WHERE student_id = %s
                AND absence_date BETWEEN %s AND %s
                """,
                (student["id"], start_date, last_day),
                fetch=True
            )

            if overlap and int(overlap[0]["c"]) > 0:

                st.caption(
                    f"{int(overlap[0]['c'])} of these day(s) already have an "
                    "absence. They will be updated with your new selection."
                )

        submit = st.button(
            "Submit Absence",
            key="absence_submit_btn"
        )

    if submit:

        if not chosen:

            st.warning(
                "Please select at least one meal."
            )

        else:

            failed = False

            for i in range(days):

                absence_day = start_date + timedelta(days=i)

                existing = execute_query(
                    """
                    SELECT id
                    FROM student_absence
                    WHERE student_id = %s
                    AND absence_date = %s
                    LIMIT 1
                    """,
                    (
                        student["id"],
                        absence_day
                    ),
                    fetch=True
                )

                if existing:

                    ok = execute_query(
                        """
                        UPDATE student_absence
                        SET
                            breakfast = %s,
                            lunch = %s,
                            dinner = %s
                        WHERE id = %s
                        """,
                        (
                            breakfast,
                            lunch,
                            dinner,
                            existing[0]["id"]
                        )
                    )

                else:

                    ok = execute_query(
                        """
                        INSERT INTO student_absence
                        (
                            student_id,
                            absence_date,
                            breakfast,
                            lunch,
                            dinner
                        )
                        VALUES
                        (%s, %s, %s, %s, %s)
                        """,
                        (
                            student["id"],
                            absence_day,
                            breakfast,
                            lunch,
                            dinner
                        )
                    )

                if not ok:
                    failed = True

            if not failed:

                st.success(
                    f"Absence submitted for {days} day(s): "
                    f"{start_date.strftime('%d-%m-%Y')} to "
                    f"{last_day.strftime('%d-%m-%Y')} "
                    f"({', '.join(chosen)})."
                )


