def student_manage():

    student = st.session_state.user

    tomorrow = date.today() + timedelta(days=1)

    page_header(
        "Upcoming Absences",
        "Plans changed? Cancel an absence before the day starts"
    )

    msg = st.session_state.pop("cancel_msg", None)

    if msg:
        st.success(msg)

    records = execute_query(
        """
        SELECT
            absence_date,
            breakfast,
            lunch,
            dinner
        FROM student_absence
        WHERE student_id = %s
        AND absence_date >= %s
        ORDER BY absence_date
        """,
        (student["id"], tomorrow),
        fetch=True
    )

    if not records:

        st.info("You have no upcoming absences.")

        return

    for r in records:
        r["student_id"] = student["student_id"]

    for i, period in enumerate(group_absences(records)):

        period_card("Upcoming Absence", period)

        if st.button(
            "Cancel this absence",
            key=f"cancel_{i}_{period['start']}"
        ):

            ok = execute_query(
                """
                DELETE FROM student_absence
                WHERE student_id = %s
                AND absence_date BETWEEN %s AND %s
                """,
                (student["id"], period["start"], period["end"])
            )

            if ok:

                st.session_state.cancel_msg = (
                    "Absence cancelled: "
                    f"{period['start'].strftime('%d-%m-%Y')} to "
                    f"{period['end'].strftime('%d-%m-%Y')}."
                )

                st.rerun()


