def student_profile():

    student = st.session_state.user

    page_header("My Profile", "Account details and password")

    stat_card("Student ID", student["student_id"], "Logged in")

    st.markdown(
        '<div class="sub-heading">Change Password</div>',
        unsafe_allow_html=True
    )

    with st.form("password_form"):

        current_pw = st.text_input(
            "Current Password",
            type="password",
            key="cp_current"
        )

        new_pw = st.text_input(
            "New Password",
            type="password",
            key="cp_new"
        )

        confirm_pw = st.text_input(
            "Confirm New Password",
            type="password",
            key="cp_confirm"
        )

        change = st.form_submit_button("Update Password")

        if change:

            if not current_pw or not new_pw or not confirm_pw:

                st.warning("Please fill all fields.")

            elif new_pw != confirm_pw:

                st.error("New passwords do not match.")

            elif len(new_pw) < 4:

                st.warning("New password must be at least 4 characters.")

            elif new_pw == current_pw:

                st.warning("New password must be different from current password.")

            elif not student_login(student["student_id"], current_pw):

                st.error("Current password is incorrect.")

            else:

                ok = execute_query(
                    "UPDATE students SET password = %s WHERE id = %s",
                    (new_pw, student["id"])
                )

                if ok:
                    st.success("Password updated successfully.")


