def student_history():

    student = st.session_state.user

    page_header("Absence History", "Your previous absence records")

    records = execute_query(
        """
        SELECT
            absence_date,
            breakfast,
            lunch,
            dinner
        FROM student_absence
        WHERE student_id = %s
        ORDER BY absence_date DESC
        """,
        (student["id"],),
        fetch=True
    )

    if not records:

        st.info("No absence history found.")

        return

    periods = group_absences(records)

    periods.sort(key=lambda x: (x["end"], x["start"]), reverse=True)

    for period in periods:

        period_card("Absence Record", period)


