def admin_home():

    page_header("Admin Home", "Food Waste Management System", back=False)

    home_hero(
        "Krishna College Mess",
        "Cook the right quantity. Waste nothing."
    )

    tomorrow = date.today() + timedelta(days=1)

    st.markdown(
        f'<div class="sub-heading">Tomorrow\'s Mess Overview '
        f'({tomorrow.strftime("%d-%m-%Y")})</div>',
        unsafe_allow_html=True
    )

    total_rows = execute_query(
        "SELECT COUNT(*) AS total FROM students",
        fetch=True
    )

    total_students = int(total_rows[0]["total"]) if total_rows else 0

    absent_rows = execute_query(
        """
        SELECT
            COUNT(*) AS submissions,
            COALESCE(SUM(breakfast), 0) AS b,
            COALESCE(SUM(lunch), 0) AS l,
            COALESCE(SUM(dinner), 0) AS d
        FROM student_absence
        WHERE absence_date = %s
        """,
        (tomorrow,),
        fetch=True
    )

    row = absent_rows[0] if absent_rows else {}

    submissions = int(row.get("submissions") or 0)
    absent_b = int(row.get("b") or 0)
    absent_l = int(row.get("l") or 0)
    absent_d = int(row.get("d") or 0)

    c1, c2, c3, c4 = st.columns(4, gap="medium")

    with c1:
        stat_card(
            "Total Students",
            total_students,
            f"{submissions} absence submission(s) for tomorrow"
        )

    with c2:
        stat_card(
            "Breakfast Expected",
            max(total_students - absent_b, 0),
            f"{absent_b} absent",
            "green"
        )

    with c3:
        stat_card(
            "Lunch Expected",
            max(total_students - absent_l, 0),
            f"{absent_l} absent",
            "orange"
        )

    with c4:
        stat_card(
            "Dinner Expected",
            max(total_students - absent_d, 0),
            f"{absent_d} absent",
            "purple"
        )

    # ---- Food waste saving summary ----
    saved_tomorrow = absent_b + absent_l + absent_d

    overall = execute_query(
        """
        SELECT
            COUNT(*) AS records,
            COALESCE(SUM(breakfast + lunch + dinner), 0) AS meals
        FROM student_absence
        """,
        fetch=True
    )

    all_meals = int(overall[0]["meals"]) if overall else 0

    st.markdown(
        '<div class="sub-heading">Food Waste Saved</div>',
        unsafe_allow_html=True
    )

    s1, s2, s3 = st.columns(3, gap="medium")

    with s1:
        stat_card(
            "Meals Saved Tomorrow",
            saved_tomorrow,
            "Meals not to be cooked for absent students",
            "green"
        )

    with s2:
        stat_card(
            "Total Meals Saved",
            all_meals,
            "Across all recorded absences",
            "orange"
        )

    with s3:
        participation = (
            round(submissions * 100 / total_students)
            if total_students else 0
        )

        stat_card(
            "Tomorrow Participation",
            f"{participation}%",
            "Students who informed the mess",
            "purple"
        )

    food_waste_banner()


