def admin_history():

    page_header("Student Absence History", "All submitted absence records")

    search = st.text_input(
        "Search by Student ID",
        key="admin_hist_search"
    ).strip().lower()

    records = execute_query(
        """
        SELECT
            s.student_id,
            a.absence_date,
            a.breakfast,
            a.lunch,
            a.dinner
        FROM student_absence a
        INNER JOIN students s
            ON a.student_id = s.id
        ORDER BY a.absence_date DESC,
                 s.student_id
        """,
        fetch=True
    )

    if not records:

        st.info(
            "No student absence records found."
        )

        return

    if search:
        records = [
            r for r in records
            if search in str(r["student_id"]).lower()
        ]

        if not records:

            st.info("No records match this Student ID.")

            return

    periods = group_absences(records)

    periods.sort(key=lambda x: (x["end"], x["start"]), reverse=True)

    for period in periods:

        period_card(
            f"Student ID: {escape(str(period['student_id']))}",
            period
        )


# =========================================================
# ABSENCE REPORT (ANY DATE + CSV)
# =========================================================

def admin_report():

    tomorrow = date.today() + timedelta(days=1)

    page_header("Absence Report", "Check absent students for any date")

    report_date = st.date_input(
        "Select date",
        value=tomorrow,
        key="report_date"
    )

    records = execute_query(
        """
        SELECT
            s.student_id,
            a.absence_date,
            a.breakfast,
            a.lunch,
            a.dinner
        FROM student_absence a
        INNER JOIN students s
            ON a.student_id = s.id
        WHERE a.absence_date >= %s
        ORDER BY s.student_id, a.absence_date
        """,
        (report_date - timedelta(days=60),),
        fetch=True
    )

    periods = [
        x for x in group_absences(records)
        if x["start"] <= report_date <= x["end"]
    ]

    if not periods:

        st.success(
            "No absence submitted for "
            + report_date.strftime("%d-%m-%Y") + "."
        )

        return

    # ---- Summary for the selected date ----
    day_rows = [
        r for r in records
        if to_date(r["absence_date"]) == report_date
    ]

    b = sum(1 for r in day_rows if r["breakfast"])
    l = sum(1 for r in day_rows if r["lunch"])
    d = sum(1 for r in day_rows if r["dinner"])

    c1, c2, c3, c4 = st.columns(4, gap="medium")

    with c1:
        stat_card("Students Absent", len(periods), report_date.strftime("%d-%m-%Y"))

    with c2:
        stat_card("Breakfast Absent", b, "", "green")

    with c3:
        stat_card("Lunch Absent", l, "", "orange")

    with c4:
        stat_card("Dinner Absent", d, "", "purple")

    # ---- CSV download ----
    lines = ["Student ID,Date,Breakfast,Lunch,Dinner,Total Duration (days)"]

    for x in sorted(periods, key=lambda p: str(p["student_id"])):

        mb, ml, md = x["meals"]

        lines.append(
            f"{x['student_id']},{report_date.strftime('%d-%m-%Y')},"
            f"{'Absent' if mb else 'Present'},"
            f"{'Absent' if ml else 'Present'},"
            f"{'Absent' if md else 'Present'},"
            f"{x['days']}"
        )

    st.download_button(
        "⬇ Download CSV",
        data="\n".join(lines),
        file_name=f"absence_report_{report_date.isoformat()}.csv",
        mime="text/csv",
        key="report_csv"
    )

    st.markdown(
        '<div class="sub-heading">Absent Students</div>',
        unsafe_allow_html=True
    )

    periods.sort(key=lambda x: str(x["student_id"]))

    for period in periods:

        period_card(
            f"Student ID: {escape(str(period['student_id']))}",
            period,
            only_absent=True
        )


# =========================================================
# REGISTERED STUDENTS
# =========================================================

def admin_students():

    page_header("Registered Students", "All student accounts and their absence totals")

    rows = execute_query(
        """
        SELECT
            s.student_id,
            COUNT(a.id) AS days,
            COALESCE(SUM(a.breakfast + a.lunch + a.dinner), 0) AS meals
        FROM students s
        LEFT JOIN student_absence a
            ON a.student_id = s.id
        GROUP BY s.id, s.student_id
        ORDER BY s.student_id
        """,
        fetch=True
    )

    if not rows:

        st.info("No students registered yet.")

        return

    search = st.text_input(
        "Search by Student ID",
        key="admin_students_search"
    ).strip().lower()

    if search:
        rows = [r for r in rows if search in str(r["student_id"]).lower()]

    c1, c2 = st.columns(2, gap="medium")

    with c1:
        stat_card("Students Shown", len(rows), "Registered accounts")

    with c2:
        stat_card(
            "Meals Saved (their total)",
            sum(int(r["meals"]) for r in rows),
            "Meals skipped with advance notice",
            "green"
        )

    st.dataframe(
        [
            {
                "Student ID": r["student_id"],
                "Absence Days": int(r["days"]),
                "Meals Skipped": int(r["meals"]),
            }
            for r in rows
        ],
        use_container_width=True,
        hide_index=True
    )


